 import {BrowserRouter, Routes,Route} from 'react-router-dom'; //BrowserRouter is a component that provides the routing context for the application. It should be used at the top level of the application, typically in the App component. It uses the HTML5 history API to keep the UI in sync with the URL.

 // Routing basically means that we can navigate to different pages in our application. In React, we can use the react-router-dom library to implement routing.


 function RootComponent(){
    return <>
    <div>Hello from root</div>
    </>
 }

function LoginComponent(){
    return<>
    <div>Hello from Login</div>
    </>
}

function SignUpcomponent(){
    return <>
    <div>Hello from SignUp</div></>
}
export default function RouteExample() {
    return <>
    <BrowserRouter>
    <Routes>  // a gorup of route will be here parent will be here 

<Route path='/' element={<RootComponent/>} />  // it takes a path prop that specifies the URL path for the route. When the URL matches this path, the component specified in the element prop will be rendered.
<Route path='/login' element= {<LoginComponent/>}/>
<Route path='/signup' element= {<SignUpComponent/>}/>

    </Routes>
    </BrowserRouter>
    </>
}
